WITH unpivoted AS (SELECT * FROM (SELECT id, device_code, humidity, pressure, temp_c FROM device_readings) src UNPIVOT (metric_value FOR measure IN (humidity AS HUMIDITY_VAL, pressure AS PRESSURE_VAL, temp_c AS TEMP_C_VAL))) SELECT CASE WHEN metric_value >= 75 THEN 'LARGE' ELSE 'SMALL' END AS metric_value_tier, SORT_ARRAY(COLLECT_SET(measure)) AS measure_list, COUNT_IF(device_code = 'DV-02') AS dv_02_events, COUNT_IF(measure = 'TEMP_C_VAL') AS temp_c_val_events FROM unpivoted GROUP BY ROLLUP (CASE WHEN metric_value >= 75 THEN 'LARGE' ELSE 'SMALL' END) ORDER BY dv_02_events;
